// TH15 Extra Stage 7 Boss10 final spell 「最初で最後の無名の弾幕」 (dual boss).
// Source mapping:
//   st07bs.ecl.txt:68-116      Boss10 entry (main boss wrapper; timerReset :88)
//   st07bs.ecl.txt:1385-1442   BossCard10 (partner call :1394, timerReset :1400)
//   st07bs.ecl.txt:1444-1545   BossCard10_at / at2 / at3
//   st07bs2.ecl.txt:62-82      BossB10 (partner spawn; timerReset :71)
//   st07bs2.ecl.txt:131-152    BossCardB10 (wait 120, then at/at2/at3)
//   st07bs2.ecl.txt:154-250    BossCardB10_at / at2 / at3
// Chapter/state, drops, sounds and ANM/BRIGHT are omitted per TH15 policy.
// The invulnerable shell keeps both LIFE values at 7000, so the source
// LIFE<=4500 / LIFE<=2000 break conditions never fire; only the TIME>=5400
// branches remain live. See report.md for the source/card frame relation.

const TIME_LIMIT: int = 7504;
const OPENING_BUFFER: int = 120;

// TH15 type 9 (kunai) and type 5 (ball2) from the shared type table.
const TH15_KUNAI: int = 496;
const TH15_BALL2: int = 432;

// Source partner bullet EX: WAIT 30 then VELTIME(a=120, r=target, s=keep angle).
// Constant angle + scalar speed ramp == step_speed; it starts the tick after entry.
xformdef PARTNER_SLOW(target: fx) {
    wait(30);
    step_speed(target, 120);
}

// Main boss: Boss10 wrapper then BossCard10 and its three synchronous sub-patterns.
async sub main_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);              // Boss() setHurtbox(40,40): radius 20
    set_hitbox(24fx);               // Boss() setHitbox(48,48): radius 24, real body
    // :70 setInvuln(180), :77-79 bombShield/flagClear/lifeSet: life is spawn HP.
    // :80 enmCall(BossB10) is done by pattern() as a parallel spawn at the same time.
    wait(4);                        // +2/+2 gates :81-83
    // :84-88 unknown569/stars/BossItemPhase/moveLimitReset omitted (display/stat/drop).
    move_to(120, -64fx, 128fx, EASE_QUAD_IN_OUT);   // :109-110 movePos + movePosTime(120,9)
    wait(180);                      // :112 -> t=184
    wait(4);                        // :1396-1400 -> BossCard10 timerReset at t=188
    // :1409-1424 spellEnd/funcSet(0)/laserCancel/sound/anm: no attack effect here.
    wait(90);                       // :1425 +90 -> at() starts at TIME 90

    // ---- BossCard10_at: 5-way ring, period 5 frames, A -= 4 deg/volley ----
    var a: angle = rand(65536) as angle;   // %RANDRAD, -pi..pi, same circle distribution
    var t: int = 90;
    sh_reset(0);
    sh_ring(0, 1);
    sh_sprite(0, TH15_KUNAI, 4);           // etSprite(0,9,4)
    sh_count(0, 5, 1);                     // etCount(0,5,1)
    sh_speed(0, 2.5fx, 0fx);               // etSpeed(0,2.5,2.5), M=1
    sh_dist(0, 14fx);                      // etDist 24 + ANIM -4*2.5
    for k in 0..1000 {                     // $B=1000; source TIME gate not reached
        sh_angle(0, a, 0deg);              // etAngle(0,%A,0.022689281), M=1 -> spread unused
        sh_fire(0);
        a = a - 4deg;                      // %A -= 0.069813
        if t >= 5400 { break; }
        wait(5);                           // C=5 waits
        t = t + 5;
    }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // :1431 etClear(640)

    // ---- BossCard10_at2: mode10 7x2 mirrored rings (-0.5deg/+0.5deg) ----
    sh_reset(0);
    sh_ring(0, 1);
    sh_sprite(0, TH15_KUNAI, 4);
    sh_count(0, 7, 1);                     // each mirrored layer emitted separately
    sh_speed(0, 2fx, 0fx);                 // paired layer speed is s0 for M=2
    sh_dist(0, 16fx);                      // 24 - 4*2
    a = rand(65536) as angle;              // %RANDRAD
    loop {
        sh_angle(0, a + 0.5deg, 0deg);     // q=0: +R(i)+0.5*delta
        sh_fire(0);
        sh_angle(0, a - 0.5deg, 0deg);     // q=1: -R(i)-0.5*delta (same point set)
        sh_fire(0);
        a = a - 6deg;                      // %A -= 0.10472
        if t >= 5400 { break; }
        wait(5);
        t = t + 5;
    }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // :1434 etClear(640)

    // ---- BossCard10_at3: 1 way x 2 mirrored layers, two volleys per frame ----
    sh_reset(0);
    sh_ring(0, 1);
    sh_sprite(0, TH15_KUNAI, 2);
    sh_count(0, 1, 2);                     // etCount(0,1,2)
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 16fx);
    a = rand(65536) as angle;              // %RANDRAD
    // Source has no TIME gate here; setInterrupt(0,0,7200) from :1420 ends the
    // segment at main TIME 7200. The card window ends 4 frames earlier at
    // TIME 7196 (card frame 7504), so stop there and retire the boss.
    while t < 7196 {
        sh_angle(0, a - 0.5deg, 1deg);     // layers A-0.5deg / A+0.5deg
        sh_fire(0);
        a = a + 222.5deg;                  // %A += 3.883222
        sh_angle(0, a - 0.5deg, 1deg);
        sh_fire(0);
        a = a + 222.5deg;
        wait(1);                           // $D=1
        t = t + 1;
    }
}

// Partner boss: BossB10 then BossCardB10 and its three sub-patterns.
async sub partner_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // BossB10 :64-73: lifeSet(7000), movePos(192,-64), timerReset, movePosTime(120,9)
    move_to(120, 64fx, 128fx, EASE_QUAD_IN_OUT);
    // :74 wait(185) is pre-empted by BossCard10's enmCall at main t=184.
    wait(184);
    // BossCardB10 :133-138 setup then wait(120) -> at() at t=304.
    wait(120);

    // ---- BossCardB10_at: 90-way fixed ring every 90 frames, A=RANDRAD ----
    var a: angle = 0deg;
    var t: int = 304;
    var w: int = 0;
    sh_reset(0);
    sh_ring(0, 1);
    sh_sprite(0, TH15_BALL2, 6);           // etSprite(0,5,6)
    sh_count(0, 90, 1);
    sh_speed(0, 2fx, 0fx);                 // etSpeed(0,2.0,0.2), M=1
    sh_dist(0, 16fx);                      // 24 - 4*2
    sh_xform(0, PARTNER_SLOW(1fx));        // VELTIME r=1.0
    loop {
        a = rand(65536) as angle;          // %RANDRAD per volley
        sh_angle(0, a, 0deg);              // mode3: alpha + R(i)
        sh_fire(0);
        w = 0;
        while w < 90 && t < 5400 {         // $B=90 checked each frame
            wait(1);
            t = t + 1;
            w = w + 1;
        }
        if t >= 5400 { break; }
    }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // :141 etClear(640)

    // ---- BossCardB10_at2: TIME already 5400 -> one ring, then return ----
    sh_xform(0, PARTNER_SLOW(1.3fx));      // VELTIME r=1.3
    a = rand(65536) as angle;
    sh_angle(0, a, 0deg);
    sh_fire(0);
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // :144 etClear(640)

    // ---- BossCardB10_at3: 90-way fixed ring every 60 frames, no TIME gate ----
    // Partner has setInterrupt time=-1; it stops when the main slot's 7200-frame
    // interrupt ends the card (partner TIME 7384 = card frame 7504).
    sh_xform(0, PARTNER_SLOW(1.5fx));      // VELTIME r=1.5
    while t < 7384 {
        a = rand(65536) as angle;
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(60);                          // $B=60
        t = t + 60;
    }
}

// Both bosses enter at source t=0 (card frame OPENING_BUFFER).
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-192fx, -64fx, 7000, 0, 0, 0, main_boss);    // Boss10
    _ = spawn_enemy(192fx, -64fx, 7000, 0, 0, 0, partner_boss);  // BossB10
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
